/* Interactive product design: synthetic records and browser-local workflow only. */
'use strict';
window.Workbench = (() => {
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const copy=x=>JSON.parse(JSON.stringify(x));
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
  const NS='mw-workbench-v3:', palette=['','#eaf2ff','#e9f6ef','#fff4d6','#fff0e6','#fdecee','#f2ecfc'];
  const colorNames=['Без цвета','Голубой','Зелёный','Жёлтый','Персиковый','Розовый','Лавандовый'];
  const baseFields=[{id:'name',label:'Товар',type:'text',width:270,source:true},{id:'supplier',label:'Поставщик',type:'enum',width:158,edit:true},{id:'stock',label:'Остаток',type:'number',width:102,source:true},{id:'qty',label:'К закупке',type:'number',width:112,edit:true},{id:'price',label:'Цена закупки',type:'number',width:125,edit:true},{id:'total',label:'Сумма',type:'number',width:135,source:true},{id:'date',label:'Срок',type:'text',width:138,edit:true},{id:'status',label:'Статус',type:'enum',width:146,edit:true},{id:'notes',label:'Заметки',type:'text',width:92}];
  let opts,main,profile,personal,shared,section='purchases',panel=null,focusTarget=null,selected=new Set(),activeCell=null,calcActive='D5',undo=[],redo=[],lastProfile=null;
  const E=()=>window.WorkbenchEngine, catalog=()=>window.GridEngine.rows;
  const product=id=>catalog().find(r=>r.id===id), role=id=>id==='owner'?'Руководитель':'Менеджер';
  const today='2026-10-02';
  const initialSettings=()=>({columns:baseFields.map(f=>({id:f.id,width:f.width,hidden:false,color:f.id==='qty'?'#eaf2ff':'',pinned:f.id==='name'})),sorts:[{field:'date',direction:'asc'}],groups:[],filters:[],filterMode:'and',search:'',density:'normal',zebra:false,rowLines:true,highlight:false});
  const initialPersonal=()=>({schema:1,settings:initialSettings(),views:[{id:'all',name:'Все позиции',settings:initialSettings()},{id:'order',name:'Нужно заказать',settings:{...initialSettings(),filters:[{field:'status',op:'eq',value:'План'}]}},{id:'suppliers',name:'По поставщикам',settings:{...initialSettings(),groups:['supplier']}}],activeView:'all',mode:'table',tab:'work',fields:[],values:{},notes:[],sheet:{A1:'Расчёт закупки',B1:'Количество',C1:'Цена',D1:'Сумма',A2:'Товар',B2:'24',C2:'420',D2:'=B2*C2',A3:'Доставка',D3:'1500',A5:'Итого',D5:'=SUM(D2:D3)'},widgets:['purchases','catalog','totals','chart'],split:true,quick:['form','paste','notes'],overdue:false,tasks:[],collapsed:[]});
  function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(NS+key));return v&&v.schema===1?v:fallback();}catch{return fallback();}}
  function load(){shared=read('shared',()=>E().createState(catalog()));shared.notes||=[];shared.attachments||={};personal=read(profile,initialPersonal);}
  function save(){try{localStorage.setItem(NS+'shared',JSON.stringify(shared));localStorage.setItem(NS+profile,JSON.stringify(personal));}catch{toast('Настройки доступны до закрытия: браузер не разрешил сохранение.');}}
  function savePersonal(){try{localStorage.setItem(NS+profile,JSON.stringify(personal));}catch{toast('Не удалось сохранить личные настройки в браузере.');}}
  const toast=t=>opts?.toast(t);
  const icon=n=>opts?.icon(n)||'';
  const editable=()=>shared.lock?.owner===profile&&!shared.request;
  const settings=()=>personal.settings;
  function fields(){return [...baseFields,...personal.fields.map(f=>({...f,personal:true,width:150}))];}
  function field(id){return fields().find(f=>f.id===id);}
  function cols(){const all=settings().columns.filter(c=>!c.hidden&&field(c.id));return [...all.filter(c=>c.pinned),...all.filter(c=>!c.pinned)];}
  const number=(n,d=0)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:d}).format(n);
  function money(n){return number(n)+' <span class="unit">₽</span>';}
  function enrich(row){const p=product(row.productId)||{};const result={...row,name:p.name||'Неизвестный товар',article:p.article||'',brand:p.brand||'',stock:p.stock??null,total:row.qty*row.price};for(const f of personal.fields){if(f.type==='formula'){const r=E().evaluate(f.expression,{fields:{'Количество':row.qty,'Цена':row.price,'Остаток':p.stock,'Сумма':result.total}});result[f.id]=r.error?'# '+r.error:r.value;}else result[f.id]=personal.values[row.id]?.[f.id]??'';}return result;}
  function allRows(){return E().rowsFor(shared,profile).map(enrich);}
  function data(){const s=settings(),defs=fields().map(f=>({...f,type:f.type==='formula'?'number':f.type}));return window.GridEngine.sortRows(window.GridEngine.filterRows(allRows(),s.filters,s.filterMode,s.search,defs),s.sorts,defs);}
  const diffs=()=>shared.drafts[profile]?E().diffRows(shared.rows,shared.drafts[profile].rows):[];
  function dispatch(action,paint=true){const before=shared.drafts[profile]?.rows&&copy(shared.drafts[profile].rows);const result=E().transition(shared,{...action,profile,at:new Date().toISOString()},catalog());if(result.error){toast(result.error);return false;}if(['edit','add'].includes(action.type)&&before){undo.push(before);if(undo.length>30)undo.shift();redo=[];}shared=result.state;shared.notes||=[];shared.attachments||={};if(['acquire','discard','submit','approve','return'].includes(action.type)){undo=[];redo=[];}save();if(paint)render();if(result.message)toast(result.message);return true;}
  function remember(){const n=document.activeElement;focusTarget=n?.id?{id:n.id}:n?.dataset?{key:Object.keys(n.dataset).find(k=>k.startsWith('wb')),value:Object.values(n.dataset)[0]}:null;}
  function dialog(title,body,actions='',wide=false){remember();let d=$('#wb-dialog');if(!d){d=document.createElement('dialog');d.id='wb-dialog';d.className='modal';d.setAttribute('aria-labelledby','wb-dialog-title');document.body.append(d);d.addEventListener('close',()=>{panel=null;if(document.activeElement!==document.body&&document.activeElement!==main&&!d.contains(document.activeElement))return;if($('#modal')?.open||$('#panel')?.open)return;if(focusTarget?.id)$('#'+CSS.escape(focusTarget.id))?.focus();else main?.focus();panel=null;});}d.style.width=wide?'680px':'460px';d.innerHTML=`<div class="drawer-head"><h2 id="wb-dialog-title">${esc(title)}</h2><button class="icon-button" data-wb-action="close" aria-label="Закрыть окно закупок">${icon('close')}</button></div><div class="drawer-body">${body}</div>${actions?`<div class="drawer-foot">${actions}</div>`:''}`;if(!d.open)d.showModal();}
  const close=()=>$('#wb-dialog')?.close();
  const btn=(action,text,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-wb-action="${action}" ${extra}>${text}</button>`;
  function selectOptions(options,value){return options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('');}
  function render(){if(!opts||!E())return;main=opts.main;main.dataset.density=settings().density;main.dataset.zebra=String(settings().zebra);main.dataset.lines=String(settings().rowLines!==false);if(section==='desk'){renderDesk();return;}renderPurchases();}
  function processBar(){const changes=diffs().length;let copyText,actions,state='';if(shared.request){copyText=`<strong>Изменения на согласовании</strong><span>${role(shared.request.author)} отправил предложение к версии ${shared.request.baseRevision}. Общая таблица пока без изменений.</span>`;actions=btn('review',profile==='owner'?'Рассмотреть изменения':'Посмотреть запрос',profile==='owner');state='is-pending';}else if(editable()){copyText=`<strong>Вы работаете в черновике <span class="mini-badge">${changes} изменений</span></strong><span>Общая версия ${shared.revision} сохранена. Другие сотрудники могут читать и комментировать.</span>`;actions=btn('release','Освободить')+btn('apply','Проверить и применить',true,changes?'':'disabled');state='is-editing';}else if(shared.lock){copyText=`<strong>Таблица в работе: ${role(shared.lock.owner)}</strong><span>Общие данные доступны для чтения. Личные колонки, расчёты и заметки можно менять.</span>`;actions='<span class="wb-scope-badge">Только просмотр</span>';}else{copyText=`<strong>Общая версия ${shared.revision}</strong><span>${shared.drafts[profile]?'Ваш черновик сохранён. Продолжите работу или откройте историю.':'Таблицу редактирует один сотрудник за раз. Изменения проходят согласование.'}</span>`;actions=btn('acquire',shared.drafts[profile]?'Продолжить работу':'Взять в работу',true);}return `<div class="wb-process-bar ${state}"><span class="wb-state-dot"></span><div class="wb-process-copy">${copyText}</div><div class="wb-process-actions">${actions}</div></div>`;}
  function renderPurchases(){const s=settings(),view=personal.views.find(v=>v.id===personal.activeView);main.innerHTML=`<section class="wb-page"><div class="titlebar"><div class="title-copy"><div class="wb-eyebrow">Рабочие таблицы / снабжение</div><h1>Закупки <span class="title-count">Октябрь</span></h1><p>Общие данные · личный способ работы</p></div><div class="title-actions">${btn('history',icon('reset')+'История')}${personal.quick.includes('form')?btn('form',icon('plus')+'Добавить позицию',true,editable()?'':'disabled title="Сначала возьмите таблицу в работу"'):''}</div></div>${processBar()}${shared.drafts[profile]?.reviewComment?`<div class="wb-return-message"><strong>Вернули на доработку:</strong> ${esc(shared.drafts[profile].reviewComment)}</div>`:''}<div class="view-strip"><div class="view-tabs" role="tablist" aria-label="Личные виды закупок">${personal.views.map(v=>`<button role="tab" class="view-tab ${v.id===personal.activeView?'active':''}" aria-selected="${v.id===personal.activeView}" data-wb-view="${v.id}">${icon('table')}${esc(v.name)}</button>`).join('')}<button class="view-add" data-wb-action="new-view" aria-label="Создать личный вид закупок">${icon('plus')}</button></div><div class="view-state"><span>Только мой вид</span>${btn('save-view','Сохранить')}</div></div><div class="wb-toolbar"><div class="wb-mode-tabs" role="tablist" aria-label="Представление закупок">${[['table','Таблица'],['board','Канбан'],['calendar','Календарь'],['pivot','Сводная'],['calc','Мои расчёты']].map(([id,name])=>`<button class="wb-mode" role="tab" data-wb-mode="${id}" aria-selected="${(personal.tab==='calc'?'calc':personal.mode)===id}">${id==='calc'?icon('copy'):''}${name}${id==='calc'?'<span class="wb-private-badge">личное</span>':''}</button>`).join('')}</div><div class="wb-shortcuts">${personal.quick.includes('paste')?btn('paste',icon('copy')+'Вставить',false,editable()?'':'disabled'):''}${personal.quick.includes('notes')?btn('notes',icon('book')+'Заметки'):''}${btn('actions',icon('more'),false, 'aria-label="Быстрые действия и правила"')}${btn('configure',icon('settings'),'','aria-label="Настроить рабочее место"')}</div></div>${personal.tab==='calc'?calcHTML():`<div class="toolbar"><div class="searchbox">${icon('search')}<input id="wb-search" aria-label="Поиск закупок" placeholder="Найти товар или поставщика…" value="${esc(s.search)}"></div><div class="tool-actions">${[['filters','filter','Фильтр',s.filters.length],['sorts','sort','Сортировка',s.sorts.length],['groups','group','Группы',s.groups.length],['columns','columns','Поля',personal.fields.length],['colors','color','Цвет',s.highlight?1:0]].map(([action,i,label,count])=>`<button class="tool-button ${count?'is-active':''}" data-wb-action="${action}">${icon(i)}${label}${count?`<span class="count">${count}</span>`:''}</button>`).join('')}</div><div class="toolbar-end">${btn('undo','↶',false,editable()&&undo.length?'aria-label="Отменить правку"':'disabled aria-label="Отменить правку"')}${btn('redo','↷',false,editable()&&redo.length?'aria-label="Повторить правку"':'disabled aria-label="Повторить правку"')}</div></div><div id="wb-content" class="wb-grid-wrap"></div><div class="wb-footer" id="wb-footer"></div>`}</section>`;if(personal.tab!=='calc'){renderData();$('#wb-search').addEventListener('input',e=>{s.search=e.target.value;savePersonal();renderData();});}else bindSheet();}
  function renderData(){const rows=data(),content=$('#wb-content');if(!content)return;content.innerHTML=personal.mode==='board'?boardHTML(rows):personal.mode==='calendar'?calendarHTML(rows):personal.mode==='pivot'?pivotHTML(rows):tableHTML(rows);$('#wb-footer').innerHTML=`<span>${rows.length} из ${allRows().length} позиций ${selected.size?`· выбрано ${selected.size}`:''}</span><span>Итого по срезу: <strong>${money(rows.reduce((a,r)=>a+r.total,0))}</strong></span><span>Демо · связанные товары из каталога</span>`;}
  function cell(row,col){const f=field(col.id),v=row[col.id];if(f.personal){if(f.type==='formula')return `<span class="${String(v).startsWith('#')?'wb-cell-error':''}" title="${esc(f.expression)}">${typeof v==='number'?number(v,2):esc(v)}</span>`;return `<input class="wb-cell-input wb-personal" data-wb-personal="${f.id}" data-row="${row.id}" aria-label="${esc(f.label)} для ${esc(row.article)}" value="${esc(v)}" ${f.type==='number'?'type="number" step="any"':''}>`;}
    if(f.id==='name')return `<button class="product-name wb-link" data-wb-product="${row.productId}">${esc(row.name)}</button><span class="cell-secondary">${esc(row.article)} · ${esc(row.brand)}</span>`;
    if(f.id==='notes'){const count=[...shared.notes,...personal.notes].filter(n=>n.rowId===row.id).length;return `<button class="wb-cell-button" data-wb-notes="${row.id}" aria-label="Заметки к ${esc(row.article)}">${icon('book')}${count||'+'}</button>`;}
    if(f.edit&&editable()){if(['supplier','status'].includes(f.id))return `<select class="wb-cell-input" data-wb-edit="${f.id}" data-row="${row.id}" aria-label="${esc(f.label)} для ${esc(row.article)}">${selectOptions(f.id==='status'?E().statuses:E().suppliers,v)}</select>`;return `<input class="wb-cell-input" type="${f.id==='date'?'date':'number'}" ${f.id==='date'?'':'min="0" step="any"'} data-wb-edit="${f.id}" data-row="${row.id}" aria-label="${esc(f.label)} для ${esc(row.article)}" value="${esc(v)}">`;}
    if(['price','total'].includes(f.id))return money(v);if(f.id==='qty'||f.id==='stock')return v===null?'—':number(v)+' <span class="unit">шт</span>';if(f.id==='status')return `<span class="tag">${esc(v)}</span>`;if(f.id==='date')return esc(v.split('-').reverse().join('.'));return esc(v);}
  function tableHTML(rows){const columns=cols(),lefts={};let left=42;columns.forEach(c=>{if(c.pinned){lefts[c.id]=left;left+=c.width;}});const changed=new Set(diffs().map(d=>d.rowId+':'+d.field));let ix=0;const rowHTML=r=>`<tr class="data-row" data-wb-row="${r.id}"><td class="row-utility pinned wb-select-cell" style="left:0"><input type="checkbox" data-wb-select="${r.id}" aria-label="Выбрать ${esc(r.article)}" ${selected.has(r.id)?'checked':''}></td>${columns.map(c=>{const f=field(c.id),tint=settings().highlight&&c.id==='qty'&&r.qty>r.stock?'#fff4d6':c.color;return `<td data-wb-cell="${c.id}" data-row="${r.id}" class="${c.pinned?'pinned ':''}${['number','formula'].includes(f.type)?'num ':''}${f.personal?'wb-personal ':''}${changed.has(r.id+':'+c.id)?'wb-changed':''}" style="${c.pinned?'left:'+lefts[c.id]+'px;':''}${tint?'--cell-tint:'+esc(tint)+';':''}">${cell(r,c)}</td>`;}).join('')}</tr>`;
    let body='';if(settings().groups.length){const walk=(nodes,depth=0)=>nodes.map(n=>{const collapsed=personal.collapsed.includes(n.key);return `<tr class="group-row"><td colspan="${columns.length+1}"><button class="group-toggle" style="padding-left:${depth*18}px" data-wb-collapse="${esc(n.key)}">${collapsed?'›':'⌄'} ${esc(field(n.field)?.label)} <strong>${esc(n.value||'Не заполнено')}</strong><span class="group-count">${n.rows.length}</span><span class="group-summary">${money(n.rows.reduce((s,r)=>s+r.total,0))}</span></button></td></tr>`+(collapsed?'':n.children?.length?walk(n.children,depth+1):n.rows.map(rowHTML).join(''));}).join('');body=walk(window.GridEngine.groupRows(rows,settings().groups,fields()));}else body=rows.map(rowHTML).join('');
    return `<table class="data-table wb-table" aria-label="Закупки, рабочая таблица" style="width:${42+columns.reduce((s,c)=>s+c.width,0)}px"><colgroup><col style="width:42px">${columns.map(c=>`<col style="width:${c.width}px">`).join('')}</colgroup><thead><tr><th class="row-utility pinned" style="left:0"><input type="checkbox" data-wb-select-all aria-label="Выбрать весь срез" ${rows.length&&rows.every(r=>selected.has(r.id))?'checked':''}></th>${columns.map(c=>`<th class="${c.pinned?'pinned':''}" style="${c.pinned?'left:'+lefts[c.id]+'px;':''}${c.color?'--cell-tint:'+esc(c.color)+';':''}"><button class="col-heading" data-wb-column="${c.id}">${field(c.id).personal?'<span class="wb-private-badge">○</span>':''}<span class="col-label">${esc(field(c.id).label)}</span>${field(c.id).source?'<span class="wb-source" title="Связанное или расчётное поле">↗</span>':icon('down')}</button></th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${columns.length+1}"><div class="wb-empty"><h3>По этим условиям нет позиций</h3><p>Измените поиск или фильтры.</p>${btn('clear-filters','Сбросить фильтры')}</div></td></tr>`}</tbody></table>`;}
  function boardHTML(rows){return `<div class="wb-board">${E().statuses.map(status=>{const group=rows.filter(r=>r.status===status);return `<section class="wb-lane"><div class="wb-lane-head"><strong>${esc(status)}</strong><span class="mini-badge">${group.length}</span></div>${group.map(r=>`<article class="wb-card"><button class="wb-card-title wb-link" data-wb-product="${r.productId}">${esc(r.name)}</button><div class="wb-card-meta">${esc(r.supplier)} · ${esc(r.date.split('-').reverse().join('.'))}</div><div class="wb-amount">${money(r.total)} <small>${r.qty} шт</small></div><div class="row-actions">${btn('edit-row','Открыть',false,`data-id="${r.id}"`)}<button class="text-button" data-wb-notes="${r.id}">Заметки</button></div></article>`).join('')||'<div class="wb-helper">Нет позиций</div>'}</section>`;}).join('')}</div>`;}
  function calendarHTML(rows){const offset=3;return `<div class="wb-calendar-wrap"><div class="wb-calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(n=>`<div class="wb-day-number">${n}</div>`).join('')}${Array.from({length:35},(_,i)=>{const day=i-offset+1,date='2026-10-'+String(day).padStart(2,'0');return `<div class="wb-day ${day===2?'is-today':''}">${day>0&&day<=31?`<span class="wb-day-number">${day}</span>${rows.filter(r=>r.date===date).map(r=>`<button class="wb-calendar-item" data-wb-action="edit-row" data-id="${r.id}">${esc(r.name)}<small>${r.qty} шт · ${esc(r.supplier)}</small></button>`).join('')}`:''}</div>`;}).join('')}</div>${rows.some(r=>!r.date.startsWith('2026-10-'))?`<div class="wb-outside-month">Вне октября: ${rows.filter(r=>!r.date.startsWith('2026-10-')).map(r=>btn('edit-row',esc(r.name)+' · '+esc(r.date),false,`data-id="${r.id}"`)).join('')}</div>`:''}</div>`;}
  function pivotHTML(rows){return `<div class="simple-page"><div class="wb-title-meta">Сумма закупок · строки: поставщик · колонки: статус</div><table class="matrix-table wb-pivot"><thead><tr><th>Поставщик</th>${E().statuses.map(s=>`<th>${esc(s)}</th>`).join('')}<th>Итого</th></tr></thead><tbody>${E().suppliers.map(s=>`<tr><td>${esc(s)}</td>${E().statuses.map(st=>`<td>${money(rows.filter(r=>r.supplier===s&&r.status===st).reduce((a,r)=>a+r.total,0))}</td>`).join('')}<td><strong>${money(rows.filter(r=>r.supplier===s).reduce((a,r)=>a+r.total,0))}</strong></td></tr>`).join('')}<tr><td><strong>Итого по срезу</strong></td>${E().statuses.map(st=>`<td>${money(rows.filter(r=>r.status===st).reduce((a,r)=>a+r.total,0))}</td>`).join('')}<td><strong>${money(rows.reduce((a,r)=>a+r.total,0))}</strong></td></tr></tbody></table><p class="wb-helper">Те же позиции и фильтры. Переключение представления не меняет данные.</p></div>`;}
  function calcHTML(){return `<div class="wb-sheet-toolbar"><span class="wb-private-badge">Только для меня</span><span class="wb-helper">Свободный лист 10 × 8 · не меняет общую таблицу</span>${btn('sheet-source','Подставить из закупки')}${btn('transfer','Перенести результат',false,editable()?'':'disabled title="Сначала возьмите таблицу в работу"')}</div><div class="wb-formula-bar"><span class="wb-cell-address" id="wb-address">${calcActive}</span><span>ƒx</span><input id="wb-formula" aria-label="Формула выбранной ячейки" value="${esc(personal.sheet[calcActive]||'')}" placeholder="=SUM(D2:D3)"></div><div class="wb-grid-wrap"><table class="wb-sheet" aria-label="Мои личные расчёты"><thead><tr><th></th>${'ABCDEFGH'.split('').map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${Array.from({length:10},(_,i)=>`<tr><th>${i+1}</th>${'ABCDEFGH'.split('').map(c=>{const a=c+(i+1),v=E().evaluate(personal.sheet[a]||'',{cells:personal.sheet});return `<td class="${a===calcActive?'wb-cell-selected':''} ${v.error?'wb-cell-error':''}"><input class="wb-sheet-input" data-wb-sheet="${a}" aria-label="Ячейка ${a}" title="${esc(v.error||personal.sheet[a]||'')}" value="${esc(v.error?'# ОШИБКА':v.value)}"></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="wb-footer"><span>Формулы: SUM, IF, MIN, MAX, ROUND · ссылки A1 и диапазоны</span><span>Ctrl+V — вставка таблицы · значения сохраняются лично</span></div>`;}
  function bindSheet(){ $$('[data-wb-sheet]',main).forEach(input=>{input.addEventListener('focus',()=>{calcActive=input.dataset.wbSheet;input.value=personal.sheet[calcActive]||'';$('#wb-address').textContent=calcActive;$('#wb-formula').value=input.value;$$('.wb-cell-selected',main).forEach(n=>n.classList.remove('wb-cell-selected'));input.parentElement.classList.add('wb-cell-selected');});input.addEventListener('input',()=>{$('#wb-formula').value=input.value;personal.sheet[input.dataset.wbSheet]=input.value;savePersonal();});input.addEventListener('change',()=>{personal.sheet[input.dataset.wbSheet]=input.value;savePersonal();});input.addEventListener('blur',()=>{const v=E().evaluate(personal.sheet[input.dataset.wbSheet]||'',{cells:personal.sheet});input.value=v.error?'# ОШИБКА':v.value;input.title=v.error||personal.sheet[input.dataset.wbSheet]||'';input.parentElement.classList.toggle('wb-cell-error',!!v.error);$$('[data-wb-sheet]',main).filter(n=>n!==input).forEach(n=>{const r=E().evaluate(personal.sheet[n.dataset.wbSheet]||'',{cells:personal.sheet});n.value=r.error?'# ОШИБКА':r.value;n.parentElement.classList.toggle('wb-cell-error',!!r.error);});});});$('#wb-formula').addEventListener('change',e=>{personal.sheet[calcActive]=e.target.value;savePersonal();render();});}
  function rowOptions(){return allRows().map(r=>[r.id,r.article+' · '+r.name]);}
  function sheetSource(){dialog('Данные для личного расчёта',`<label class="field-label">Позиция<select id="wb-source-row">${selectOptions(rowOptions(),[...selected][0])}</select></label><p class="wb-helper">Товар, количество и цена попадут в A2, B2 и C2. Это снимок текущей строки: повторите подстановку, чтобы обновить его.</p>`,btn('source-save','Подставить',true));}
  function transfer(){if(!editable())return toast('Сначала возьмите таблицу в работу.');const r=E().evaluate(personal.sheet[calcActive]||'',{cells:personal.sheet});if(r.error||typeof r.value!=='number'||!Number.isFinite(r.value)||r.value<0)return toast('Для переноса выберите ячейку с неотрицательным числом.');dialog('Перенести результат в черновик',`<p><strong>${calcActive} = ${number(r.value,2)}</strong></p><label class="field-label">Позиция<select id="wb-transfer-row">${selectOptions(rowOptions(),[...selected][0])}</select></label><label class="field-label">Поле<select id="wb-transfer-field"><option value="qty">К закупке</option><option value="price">Цена закупки</option></select></label><p class="wb-helper">Изменится только ваш черновик. Общая версия обновится после согласования.</p>`,btn('transfer-save','Перенести в черновик',true,`data-value="${r.value}"`));}
  function entryForm(id){const row=allRows().find(r=>r.id===id),p=product(row?.productId)||catalog()[0],can=editable();if(!row&&!can)return toast('Сначала возьмите таблицу в работу.');dialog(row?'Позиция закупки':'Добавить позицию',`<div class="wb-form-grid"><label class="field-label wb-form-full">Товар из каталога<select id="wb-form-product" ${can?'':'disabled'}>${selectOptions(catalog().map(p=>[p.id,p.article+' · '+p.name]),p.id)}</select></label><div class="wb-related-card wb-form-full" id="wb-form-related">${esc(p.brand)} · остаток ${p.stock} шт · ${esc(p.article)}</div><label class="field-label">Количество<input id="wb-form-qty" type="number" min="0" step="any" value="${row?.qty??10}" ${can?'':'disabled'}></label><label class="field-label">Цена закупки, ₽<input id="wb-form-price" type="number" min="0" step="any" value="${row?.price??p.cost??0}" ${can?'':'disabled'}></label><label class="field-label">Срок<input id="wb-form-date" type="date" value="${row?.date||'2026-10-12'}" ${can?'':'disabled'}></label><label class="field-label">Поставщик<select id="wb-form-supplier" ${can?'':'disabled'}>${selectOptions(E().suppliers,row?.supplier)}</select></label><label class="field-label">Статус<select id="wb-form-status" ${can?'':'disabled'}>${selectOptions(E().statuses,row?.status||'План')}</select></label><label class="field-label wb-form-full">Вложения<input id="wb-form-files" type="file" multiple ${can?'':'disabled'}><span class="wb-helper">В макете сохраняются только названия и размеры файлов. Содержимое не загружается.</span></label><div class="wb-helper wb-form-full">${esc((personal.attachments?.[id]||[]).map(f=>f.name+' ('+number(f.size)+' Б)').join(', '))}</div></div>`,(can?btn('form-save',row?'Сохранить в черновик':'Добавить в черновик',true,`data-id="${id||''}"`):'')+btn('close','Закрыть'),true);$('#wb-form-product').addEventListener('change',e=>{const p=product(e.target.value);$('#wb-form-related').textContent=p.brand+' · остаток '+p.stock+' шт · '+p.article;$('#wb-form-price').value=p.cost??0;});}
  function diffHTML(changes){const format=(f,v)=>f==='productId'?(product(v)?.article+' · '+product(v)?.name):v??'—';const expanded=changes.flatMap(d=>d.kind==='add'?['productId','supplier','qty','price','date','status'].map(f=>({...d,field:f,before:null,after:d.after[f]})):d);return `<div class="wb-diff-wrap"><table class="wb-diff-table"><thead><tr><th>Позиция / поле</th><th>Было</th><th>Предложено</th></tr></thead><tbody>${expanded.map(d=>{const r=shared.request?.rows.find(r=>r.id===d.rowId)||shared.drafts[profile]?.rows.find(r=>r.id===d.rowId)||shared.rows.find(r=>r.id===d.rowId);return `<tr><td>${esc(product(r?.productId)?.article||d.rowId)}<small>${esc(d.field==='productId'?'Товар':field(d.field)?.label||d.field)}${d.kind==='add'?' · новая позиция':''}</small></td><td class="wb-before">${esc(d.kind==='add'?'—':format(d.field,d.before))}</td><td class="wb-after">${esc(format(d.field,d.after))}</td></tr>`;}).join('')}</tbody></table></div><p class="wb-helper">Сумма предложенной закупки: ${money((shared.request?.rows||shared.drafts[profile]?.rows||[]).reduce((s,r)=>s+r.qty*r.price,0))}</p>`;}
  function applyDialog(){if(!editable())return;const changes=diffs();if(!changes.length)return toast('В черновике нет изменений.');dialog('Проверить изменения',`<p>${changes.length} изменений к общей версии ${shared.revision}. Закупки требуют согласования руководителя.</p>${diffHTML(changes)}<label class="field-label">Комментарий к предложению<textarea id="wb-approval-comment" rows="2" placeholder="Зачем меняем закупку…"></textarea></label><p class="wb-helper">После отправки таблица будет ждать решения руководителя. Ваши личные поля и расчёты в запрос не входят.</p>`,btn('submit','Отправить на согласование',true)+btn('close','Вернуться'),true);}
  function reviewDialog(){const q=shared.request;if(!q)return;dialog('Согласование закупки',`<div class="wb-approval-comment"><strong>${role(q.author)} · версия ${q.baseRevision}</strong><p>${esc(q.comment||'Без комментария')}</p></div>${diffHTML(E().diffRows(shared.rows,q.rows))}${profile==='owner'?'<label class="field-label">Комментарий при возврате<textarea id="wb-return-comment" rows="2" placeholder="Что нужно поправить…"></textarea></label>':'<p class="wb-helper">Решение доступно руководителю. Переключите демо-профиль в верхней панели.</p>'}`,profile==='owner'?btn('approve','Согласовать и применить',true)+btn('return','Вернуть на доработку'):btn('close','Закрыть'),true);}
  function notesDialog(rowId=''){panel={type:'notes',rowId};const notes=[...shared.notes,...personal.notes].filter(n=>(n.rowId||'')===rowId).sort((a,b)=>b.at.localeCompare(a.at));dialog(rowId?'Заметки к позиции':'Заметки к таблице',`<p class="wb-helper">Общие заметки доступны обоим демо-профилям, личные — только текущему. Комментировать можно, пока таблица занята.</p><div>${notes.map(n=>`<article class="wb-note"><div class="wb-note-head"><strong>${role(n.author)}</strong><span class="wb-note-scope">${n.scope==='private'?'Личная':'Общая'}</span></div><div class="wb-note-body">${esc(n.text)}</div></article>`).join('')||'<div class="wb-empty">Пока нет заметок</div>'}</div><label class="field-label">Новая заметка<textarea id="wb-note-text" rows="3" maxlength="2000" placeholder="Добавьте контекст…"></textarea></label><label class="field-label">Кому видна<select id="wb-note-scope"><option value="private">Только мне</option><option value="team">Всей команде</option></select></label>`,btn('note-save','Добавить заметку',true,`data-row="${rowId}"`));}
  function historyDialog(){dialog('История общей таблицы',`<p class="wb-helper">Версия ${shared.revision} · синтетические данные в этом браузере</p><div class="wb-timeline">${shared.history.slice().reverse().map(h=>`<article class="wb-timeline-item"><strong>${esc(h.description)}</strong><small>${role(h.profile||h.actor)} · ${new Date(h.at).toLocaleString('ru-RU')}</small></article>`).join('')||'<div class="wb-empty">История появится после начала работы с таблицей.</div>'}</div>${shared.drafts[profile]?'<p class="wb-helper">У вас есть сохранённый черновик.</p>':''}`,btn('close','Закрыть')+(shared.drafts[profile]&&!shared.request?btn('discard-confirm','Удалить мой черновик'):''));}
  function pasteDialog(){if(!editable())return toast('Сначала возьмите таблицу в работу.');dialog('Вставить диапазон',`<p class="wb-helper">Скопируйте ячейки из таблицы. Столбцы: количество, цена. Строки начнутся с выбранной позиции в текущем срезе. Весь диапазон проверяется до записи.</p><label class="field-label">Начальная позиция<select id="wb-paste-row">${selectOptions(pasteRows().map(r=>[r.id,r.article+' · '+r.name]),[...selected][0])}</select></label><label class="field-label">Данные, разделённые табуляцией<textarea id="wb-paste-text" rows="6" placeholder="24&#9;420&#10;12&#9;560"></textarea></label>`,btn('paste-save','Вставить в черновик',true));}
  function pasteRows(){const rows=data();if(personal.tab!=='calc'&&personal.mode==='table')return $$('[data-wb-row]',main).map(n=>rows.find(r=>r.id===n.dataset.wbRow)).filter(Boolean);return rows;}
  function pasteGrid(text,rowId,fieldId,explicit=false){if(!editable())return toast('Общие данные доступны только для чтения.');const lines=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(l=>l.split('\t')),rs=pasteRows(),start=rs.findIndex(r=>r.id===rowId),columns=explicit?['qty','price']:cols().map(c=>c.id),ci=columns.indexOf(fieldId);if(start<0||ci<0||start+lines.length>rs.length)return toast('Диапазон выходит за строки текущего среза.');const patches=[];for(let i=0;i<lines.length;i++)for(let j=0;j<lines[i].length;j++){const f=columns[ci+j];if(!field(f)?.edit)return toast('Диапазон затрагивает поле только для чтения. Ничего не изменено.');patches.push({rowId:rs[start+i].id,field:f,value:lines[i][j]});}return dispatch({type:'edit',patches});}
  function undoDraft(forward=false){if(!editable())return;const from=forward?redo:undo,to=forward?undo:redo;if(!from.length)return;to.push(copy(shared.drafts[profile].rows));shared.drafts[profile].rows=from.pop();shared.drafts[profile].updatedAt=new Date().toISOString();save();render();toast(forward?'Правка повторена в черновике.':'Правка отменена в черновике.');}
  function settingsDialog(type){panel={type};const s=settings(),options=fields().filter(f=>f.id!=='notes').map(f=>[f.id,f.label]);let body='',actions='';if(type==='columns'||type==='colors'){body=`<p class="wb-helper">Настройки видны только вам. Поля со стрелкой связаны с каталогом или вычисляются.</p><div class="wb-settings-list">${s.columns.filter(c=>field(c.id)).map((c,i)=>`<div class="wb-settings-row"><label><input type="checkbox" data-wb-visible="${c.id}" ${c.hidden?'':'checked'}> ${esc(field(c.id).label)} ${field(c.id).personal?'<span class="wb-private-badge">моё</span>':''}</label>${type==='colors'?`<select data-wb-color="${c.id}" aria-label="Цвет ${esc(field(c.id).label)}">${selectOptions(palette.map((v,i)=>[v,colorNames[i]]),c.color)}</select>`:`<div class="wb-inline-actions"><button class="icon-button" data-wb-move="${c.id}" data-dir="-1" aria-label="Поле выше" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-wb-move="${c.id}" data-dir="1" aria-label="Поле ниже" ${i===s.columns.length-1?'disabled':''}>↓</button><button class="icon-button ${c.pinned?'is-active':''}" data-wb-pin="${c.id}" aria-label="${c.pinned?'Открепить':'Закрепить'} ${esc(field(c.id).label)}" aria-pressed="${c.pinned}">${icon('pin')}</button><input style="width:68px" type="number" min="80" max="480" data-wb-width="${c.id}" value="${c.width}" aria-label="Ширина ${esc(field(c.id).label)}"></div>`}</div>`).join('')}</div>${type==='colors'?`<label class="wb-settings-row"><span>Подсвечивать количество выше текущего остатка</span><input type="checkbox" data-wb-setting="highlight" ${s.highlight?'checked':''}></label>`:''}`;actions=(type==='colors'?btn('appearance-presets','Пресеты оформления'):btn('personal-field','Добавить личное поле'))+btn('close','Готово',true);}
    if(type==='sorts'){body=`<p class="wb-helper">Порядок правил задаёт приоритет. Первая сортировка — основная.</p>${s.sorts.map((r,i)=>`<div class="wb-settings-row"><span>${i+1}</span><select data-wb-rule="sorts:${i}:field" aria-label="Поле сортировки ${i+1}">${selectOptions(options,r.field)}</select><select data-wb-rule="sorts:${i}:direction" aria-label="Направление сортировки ${i+1}">${selectOptions([['asc','По возрастанию'],['desc','По убыванию']],r.direction)}</select><button class="icon-button" data-wb-rule-up="sorts:${i}" aria-label="Повысить приоритет" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-wb-rule-delete="sorts:${i}" aria-label="Удалить сортировку">×</button></div>`).join('')||'<div class="wb-empty">Порядок исходных строк</div>'}`;actions=btn('add-sort','Добавить сортировку')+btn('close','Готово',true);}
    if(type==='filters'){body=`<label class="field-label">Соединять условия<select data-wb-setting="filterMode">${selectOptions([['and','Все условия · И'],['or','Любое условие · ИЛИ']],s.filterMode)}</select></label>${s.filters.map((r,i)=>`<div class="wb-settings-row"><select data-wb-rule="filters:${i}:field" aria-label="Поле фильтра ${i+1}">${selectOptions(options,r.field)}</select><select data-wb-rule="filters:${i}:op" aria-label="Условие ${i+1}">${selectOptions([['eq','Равно'],['neq','Не равно'],['contains','Содержит'],['gt','Больше'],['lt','Меньше'],['empty','Пусто'],['notEmpty','Заполнено']],r.op)}</select><input data-wb-rule="filters:${i}:value" aria-label="Значение фильтра ${i+1}" value="${esc(r.value)}" placeholder="Значение"><button class="icon-button" data-wb-rule-delete="filters:${i}" aria-label="Удалить фильтр">×</button></div>`).join('')||'<div class="wb-empty">Все позиции без ограничений</div>'}`;actions=btn('add-filter','Добавить условие')+btn('close','Готово',true);}
    if(type==='groups'){body=`<p class="wb-helper">До двух уровней вложенности. Итоги пересчитываются по вашему срезу.</p>${s.groups.map((id,i)=>`<label class="field-label">Уровень ${i+1}<select data-wb-group="${i}">${selectOptions([['supplier','Поставщик'],['status','Статус']],id)}</select><button class="text-button" data-wb-group-delete="${i}">Убрать уровень</button></label>`).join('')||'<div class="wb-empty">Плоская таблица</div>'}`;actions=btn('add-group','Добавить уровень',false,s.groups.length>=2?'disabled':'')+btn('close','Готово',true);}
    dialog({columns:'Мои поля',colors:'Цвета и акценты',sorts:'Сортировка',filters:'Фильтры',groups:'Группировка'}[type],body,actions,true);
  }
  function personalFieldDialog(){dialog('Добавить личное поле',`<p class="wb-helper">Поле появится только в ваших видах. Общая структура закупок останется единой.</p><label class="field-label">Название<input id="wb-field-name" maxlength="40" placeholder="Например, приоритет"></label><label class="field-label">Тип<select id="wb-field-type"><option value="text">Текст или метка</option><option value="number">Число</option><option value="formula">Формула</option></select></label><label class="field-label">Формула для каждой строки<input id="wb-field-formula" placeholder="=[Количество]*[Цена]*1.1" value="=[Количество]*[Цена]"></label><p class="wb-helper">Доступны [Количество], [Цена], [Остаток], [Сумма]. Формулы не меняют исходные поля.</p>`,btn('field-save','Создать личное поле',true));}
  function configureDialog(){const titles={purchases:'Таблица закупок',catalog:'Связанный каталог',totals:'Мои показатели',chart:'Закупки по поставщикам'};dialog('Моё рабочее место',`<label class="wb-settings-row"><span>Две таблицы рядом</span><input type="checkbox" data-wb-personal-setting="split" ${personal.split?'checked':''}></label><label class="field-label">Плотность таблицы<select data-wb-setting="density">${selectOptions([['compact','Компактная'],['normal','Обычная'],['comfortable','Свободная']],settings().density)}</select></label><label class="wb-settings-row"><span>Чередовать фон строк</span><input type="checkbox" data-wb-setting="zebra" ${settings().zebra?'checked':''}></label><label class="wb-settings-row"><span>Вертикальные линии таблицы</span><input type="checkbox" data-wb-setting="rowLines" ${settings().rowLines!==false?'checked':''}></label><h3>Виджеты и их порядок</h3>${Object.entries(titles).map(([id,title])=>`<div class="wb-settings-row"><label><input type="checkbox" data-wb-widget="${id}" ${personal.widgets.includes(id)?'checked':''}> ${title}</label><span>${personal.widgets.includes(id)?personal.widgets.indexOf(id)+1:''}</span><button class="icon-button" data-wb-widget-up="${id}" ${personal.widgets.indexOf(id)<=0?'disabled':''} aria-label="Поднять ${title}">↑</button></div>`).join('')}<h3>Кнопки под рукой</h3>${[['paste','Вставка диапазона'],['notes','Заметки'],['form','Форма ввода']].map(([id,title])=>`<label class="wb-settings-row"><span>${title}</span><input type="checkbox" data-wb-quick="${id}" ${personal.quick.includes(id)?'checked':''}></label>`).join('')}<p class="wb-helper">Изменения сохраняются для ${role(profile).toLowerCase()} в этом браузере.</p>`,btn('desk','Открыть моё рабочее место')+btn('close','Готово',true));}
  function actionsDialog(){dialog('Мои быстрые действия',`<div class="wb-settings-list"><div class="wb-settings-row"><span>Задача по выбранным позициям<br><small>${selected.size} выбрано · только в моём рабочем месте</small></span>${btn('task','Создать',false,selected.size?'':'disabled')}</div><label class="wb-settings-row"><span>Показывать просроченные закупки<br><small>Личное правило: срок до 02.10 и статус ≠ «Получено»</small></span><input type="checkbox" data-wb-personal-setting="overdue" ${personal.overdue?'checked':''}></label></div><p class="wb-helper">Правило выделяет позиции на вашем рабочем экране. Оно не меняет общие данные и ничего не отправляет наружу.</p>`,btn('configure','Выбрать кнопки')+btn('close','Готово',true));}
  function renderDesk(){const rs=shared.rows.map(enrich),sum=rs.reduce((a,r)=>a+r.total,0),widgetTitles={purchases:'Закупки',catalog:'Связанные товары',totals:'Общая версия в цифрах',chart:'Сумма по поставщикам'};const mini=(rows,kind)=>`<table class="wb-compact-table"><thead><tr><th>Товар</th><th>${kind==='catalog'?'Остаток':'К закупке'}</th><th>${kind==='catalog'?'Бренд':'Статус'}</th></tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr><td><button class="wb-link" data-wb-product="${kind==='catalog'?r.id:r.productId}">${esc(r.name)}</button><small>${esc(r.article)}</small></td><td>${kind==='catalog'?r.stock:r.qty}</td><td>${esc(kind==='catalog'?r.brand:r.status)}</td></tr>`).join('')}</tbody></table>`;main.innerHTML=`<section class="wb-page"><div class="titlebar"><div class="title-copy"><div class="wb-eyebrow">Личное пространство</div><h1>Моё рабочее место</h1><p>Ваши таблицы, показатели и задачи рядом</p></div><div class="title-actions">${btn('configure',icon('settings')+'Настроить')}</div></div><div class="wb-toolbar"><span class="wb-private-badge">${role(profile)} · только для меня</span>${btn('purchases',icon('table')+'Закупки')}${btn('catalog',icon('box')+'Каталог')}<span class="wb-helper">Закреплённые разделы</span></div><div class="wb-workspace-grid ${personal.split?'':'single'}">${personal.widgets.map(id=>`<section class="wb-widget ${id==='totals'?'wide':''}"><div class="wb-widget-head"><h2>${widgetTitles[id]}</h2><button class="icon-button" data-wb-widget-up="${id}" aria-label="Поднять виджет ${widgetTitles[id]}" ${personal.widgets.indexOf(id)===0?'disabled':''}>↑</button></div><div class="wb-widget-body">${id==='purchases'?mini(rs,'purchases'):id==='catalog'?mini(catalog(),'catalog'):id==='totals'?`<div class="wb-kpis"><div><span>План закупок</span><strong>${money(sum)}</strong></div><div><span>Позиций</span><strong>${rs.length}</strong></div><div><span>На согласовании</span><strong>${shared.request?'1 запрос':'Нет'}</strong></div><div><span>Рабочая версия</span><strong>${shared.revision}</strong></div></div>`:`<div class="wb-chart">${E().suppliers.map(s=>{const v=rs.filter(r=>r.supplier===s).reduce((a,r)=>a+r.total,0);return `<div class="wb-chart-row"><span class="wb-chart-label">${esc(s)}</span><div class="wb-chart-track"><div class="wb-chart-bar" style="width:${sum?v/sum*100:0}%"></div></div><strong>${money(v)}</strong></div>`;}).join('')}</div>`}</div></section>`).join('')}${personal.tasks.length?`<section class="wb-widget wide"><div class="wb-widget-head"><h2>Мои задачи</h2></div><div class="wb-widget-body">${personal.tasks.map(t=>`<label class="wb-settings-row"><span>${esc(t.text)}<small>${t.rows.length} позиций</small></span><input type="checkbox" data-wb-task="${t.id}" ${t.done?'checked':''} aria-label="Задача выполнена"></label>`).join('')}</div></section>`:''}${personal.overdue?`<section class="wb-widget wide"><div class="wb-widget-head"><h2>Требуют внимания</h2><span class="wb-private-badge">Моё правило</span></div><div class="wb-widget-body">${rs.filter(r=>r.date<today&&r.status!=='Получено').length?mini(rs.filter(r=>r.date<today&&r.status!=='Получено'),'purchases'):'Нет просроченных позиций по общей версии.'}</div></section>`:''}${!personal.widgets.length?'<div class="wb-empty">Добавьте нужные виджеты через «Настроить».</div>':''}</div><div class="wb-footer"><span>Сводки показывают общую версию, черновики доступны в закупках.</span><span>Демонстрация · данные в браузере</span></div></section>`;}
  function moveItem(array,index,delta){const target=index+delta;if(index<0||target<0||target>=array.length)return;[array[index],array[target]]=[array[target],array[index]];}
  function refreshSettings(){savePersonal();render();if(panel?.type&&['columns','colors','sorts','groups','filters'].includes(panel.type))settingsDialog(panel.type);}
  function openAppearancePresets(){
    close();
    window.AppearancePresets.open({tableId:'purchases',profile,label:'Закупки',toast,
      capture:()=>({density:settings().density,zebra:settings().zebra,rowLines:settings().rowLines!==false,highlight:settings().highlight,columns:settings().columns.map(c=>({id:c.id,color:c.color||''}))}),
      apply:config=>{
        const patch=target=>{
          target.density=config.density;target.zebra=config.zebra;target.rowLines=config.rowLines;target.highlight=config.highlight===true;
          const colors=new Map(config.columns.map(c=>[c.id,c.color]));
          target.columns.forEach(c=>{if(colors.has(c.id)&&field(c.id))c.color=colors.get(c.id)||'';});
        };
        const next=copy(personal);patch(next.settings);
        const saved=next.views.find(v=>v.id===next.activeView);if(saved)patch(saved.settings);
        try{localStorage.setItem(NS+profile,JSON.stringify(next));}catch{return false;}
        personal=next;render();return true;
      }
    });
  }
  function action(name,node){switch(name){
    case 'appearance-presets':openAppearancePresets();break;
    case 'close':close();break;
    case 'acquire':dispatch({type:'acquire'});break;
    case 'release':dialog('Освободить таблицу', '<p>Черновик сохранится у вас. Другой сотрудник сможет взять общую таблицу в работу. Если он изменит общую версию, ваш черновик потребуется пересобрать.</p>',btn('release-save','Сохранить и освободить',true)+btn('close','Продолжить работу'));break;
    case 'release-save':if(dispatch({type:'release'}))close();break;
    case 'discard-confirm':dialog('Удалить мой черновик', '<p>Будут удалены только ваши неопубликованные изменения закупки. Общая версия, личные расчёты и заметки сохранятся.</p>',btn('discard','Удалить черновик',true)+btn('close','Отмена'));break;
    case 'discard':if(dispatch({type:'discard'}))close();break;
    case 'form':entryForm();break;
    case 'edit-row':entryForm(node.dataset.id);break;
    case 'form-save':{const row={productId:$('#wb-form-product').value,qty:$('#wb-form-qty').value,price:$('#wb-form-price').value,date:$('#wb-form-date').value,supplier:$('#wb-form-supplier').value,status:$('#wb-form-status').value},files=[...$('#wb-form-files').files].map(f=>({name:f.name,size:f.size})),id=node.dataset.id;const ok=dispatch(id?{type:'edit',patches:Object.entries(row).map(([field,value])=>({rowId:id,field,value}))}:{type:'add',row});if(ok){const key=id||shared.drafts[profile].rows.at(-1).id;personal.attachments||={};if(files.length){personal.attachments[key]=files;savePersonal();}close();}break;}
    case 'apply':applyDialog();break;
    case 'submit':if(dispatch({type:'submit',comment:$('#wb-approval-comment').value}))close();break;
    case 'review':reviewDialog();break;
    case 'approve':if(dispatch({type:'approve'}))close();break;
    case 'return':if(dispatch({type:'return',comment:$('#wb-return-comment').value}))close();break;
    case 'notes':notesDialog();break;
    case 'note-save':{const text=$('#wb-note-text').value.trim(),scope=$('#wb-note-scope').value,rowId=node.dataset.row||'';if(!text)return toast('Введите текст заметки.');const note={id:uid(),text,scope,rowId,author:profile,at:new Date().toISOString()};if(scope==='private'){personal.notes.push(note);savePersonal();}else{shared.notes.push(note);save();}render();notesDialog(rowId);break;}
    case 'history':historyDialog();break;
    case 'undo':undoDraft();break;
    case 'redo':undoDraft(true);break;
    case 'paste':pasteDialog();break;
    case 'paste-save':if(pasteGrid($('#wb-paste-text').value,$('#wb-paste-row').value,'qty',true))close();break;
    case 'sheet-source':sheetSource();break;
    case 'source-save':{const r=allRows().find(r=>r.id===$('#wb-source-row').value);if(!r)return;Object.assign(personal.sheet,{A2:r.name,B2:String(r.qty),C2:String(r.price)});savePersonal();close();render();toast('Снимок строки подставлен в личный расчёт.');break;}
    case 'transfer':transfer();break;
    case 'transfer-save':if(dispatch({type:'edit',patches:[{rowId:$('#wb-transfer-row').value,field:$('#wb-transfer-field').value,value:node.dataset.value}]}))close();break;
    case 'columns':case 'colors':case 'sorts':case 'groups':case 'filters':settingsDialog(name);break;
    case 'add-sort':{const f=fields().find(f=>f.id!=='notes'&&!settings().sorts.some(r=>r.field===f.id));if(f)settings().sorts.push({field:f.id,direction:'asc'});refreshSettings();break;}
    case 'add-filter':settings().filters.push({field:'supplier',op:'contains',value:''});refreshSettings();break;
    case 'add-group':{const f=['supplier','status'].find(f=>!settings().groups.includes(f));if(f)settings().groups.push(f);refreshSettings();break;}
    case 'clear-filters':settings().filters=[];settings().search='';savePersonal();render();break;
    case 'personal-field':personalFieldDialog();break;
    case 'field-save':{const label=$('#wb-field-name').value.trim(),type=$('#wb-field-type').value,expression=$('#wb-field-formula').value;if(!label)return toast('Укажите название личного поля.');if(fields().some(f=>f.label===label))return toast('Поле с таким названием уже есть.');if(type==='formula'){const test=E().evaluate(expression,{fields:{Количество:1,Цена:1,Остаток:1,Сумма:1}});if((test.error&&!/Деление на ноль/i.test(test.error))||!expression.startsWith('='))return toast(test.error||'Начните формулу со знака =.');}const id='private-'+uid();personal.fields.push({id,label,type,expression});settings().columns.push({id,width:160,hidden:false,pinned:false,color:'#f2ecfc'});savePersonal();render();close();toast('Личное поле добавлено справа.');break;}
    case 'new-view':dialog('Новый личный вид','<label class="field-label">Название<input id="wb-view-name" maxlength="40" placeholder="Например, мои поставщики"></label><p class="wb-helper">Сохранит текущие поля, цвета, фильтры, сортировки и группы. Исходные данные общие.</p>',btn('view-create','Создать вид',true));break;
    case 'view-create':{const name=$('#wb-view-name').value.trim();if(!name)return toast('Укажите название вида.');const id=uid();personal.views.push({id,name,settings:copy(settings())});personal.activeView=id;savePersonal();render();close();break;}
    case 'save-view':{const v=personal.views.find(v=>v.id===personal.activeView);v.settings=copy(settings());savePersonal();toast('Личный вид сохранён.');break;}
    case 'configure':panel={type:'configure'};configureDialog();break;
    case 'actions':panel={type:'actions'};actionsDialog();break;
    case 'task':dialog('Личная задача',`<p>${selected.size} позиций из закупок</p><label class="field-label">Что сделать<input id="wb-task-text" maxlength="140" value="Проверить условия поставки"></label>`,btn('task-save','Сохранить задачу',true));break;
    case 'task-save':{const text=$('#wb-task-text').value.trim();if(!text)return toast('Введите текст задачи.');personal.tasks.push({id:uid(),text,rows:[...selected],done:false});savePersonal();close();toast('Задача добавлена в моё рабочее место.');break;}
    case 'desk':close();opts.navigate('desk');break;
    case 'purchases':close();opts.navigate('purchases');break;
    case 'catalog':close();opts.navigate('products');break;
  }}
  document.addEventListener('click',e=>{if(!opts)return;const n=e.target.closest('[data-wb-action],[data-wb-view],[data-wb-mode],[data-wb-product],[data-wb-notes],[data-wb-column],[data-wb-collapse],[data-wb-pin],[data-wb-move],[data-wb-rule-delete],[data-wb-rule-up],[data-wb-group-delete],[data-wb-widget-up]');const cell=e.target.closest('[data-wb-cell]');if(cell){activeCell={rowId:cell.dataset.row,field:cell.dataset.wbCell};}if(!n)return;if(n.dataset.wbAction){action(n.dataset.wbAction,n);return;}if(n.dataset.wbView){personal.activeView=n.dataset.wbView;personal.settings=copy(personal.views.find(v=>v.id===personal.activeView).settings);for(const f of personal.fields)if(!settings().columns.some(c=>c.id===f.id))settings().columns.push({id:f.id,width:160,hidden:true,pinned:false,color:''});savePersonal();render();}
    if(n.dataset.wbMode){personal.tab=n.dataset.wbMode==='calc'?'calc':'work';if(personal.tab!=='calc')personal.mode=n.dataset.wbMode;savePersonal();render();}
    if(n.dataset.wbProduct)opts.openProduct(n.dataset.wbProduct);
    if(n.dataset.wbNotes)notesDialog(n.dataset.wbNotes);
    if(n.dataset.wbColumn)settingsDialog('columns');
    if(n.dataset.wbCollapse){const k=n.dataset.wbCollapse;personal.collapsed=personal.collapsed.includes(k)?personal.collapsed.filter(x=>x!==k):[...personal.collapsed,k];savePersonal();renderData();}
    if(n.dataset.wbPin){const c=settings().columns.find(c=>c.id===n.dataset.wbPin);c.pinned=!c.pinned;refreshSettings();}
    if(n.dataset.wbMove){const i=settings().columns.findIndex(c=>c.id===n.dataset.wbMove);moveItem(settings().columns,i,Number(n.dataset.dir));refreshSettings();}
    if(n.dataset.wbRuleDelete){const [key,i]=n.dataset.wbRuleDelete.split(':');settings()[key].splice(Number(i),1);refreshSettings();}
    if(n.dataset.wbRuleUp){const [key,i]=n.dataset.wbRuleUp.split(':');moveItem(settings()[key],Number(i),-1);refreshSettings();}
    if(n.dataset.wbGroupDelete){settings().groups.splice(Number(n.dataset.wbGroupDelete),1);personal.collapsed=[];refreshSettings();}
    if(n.dataset.wbWidgetUp){moveItem(personal.widgets,personal.widgets.indexOf(n.dataset.wbWidgetUp),-1);savePersonal();render();if($('#wb-dialog')?.open)configureDialog();}
  });
  document.addEventListener('change',e=>{if(!opts)return;const n=e.target,d=n.dataset;if(d.wbEdit){const ok=dispatch({type:'edit',patches:[{rowId:d.row,field:d.wbEdit,value:n.value}]},false);const row=allRows().find(r=>r.id===d.row);n.value=row[d.wbEdit];if(ok){const tr=n.closest('tr');tr?.querySelectorAll('[data-wb-cell]').forEach(td=>{const f=field(td.dataset.wbCell);if(f.id==='total'||f.type==='formula')td.innerHTML=cell(row,settings().columns.find(c=>c.id===f.id));td.classList.toggle('wb-changed',diffs().some(x=>x.rowId===row.id&&x.field===f.id));});const badge=$('.wb-process-copy .mini-badge');if(badge)badge.textContent=diffs().length+' изменений';const apply=$('[data-wb-action="apply"]');if(apply)apply.disabled=!diffs().length;$('[data-wb-action="undo"]').disabled=!undo.length;$('[data-wb-action="redo"]').disabled=!redo.length;const rows=data();$('#wb-footer').innerHTML=`<span>${rows.length} позиций · черновик</span><span>Итого по срезу: <strong>${money(rows.reduce((a,r)=>a+r.total,0))}</strong></span><span>Сортировки и фильтры обновятся при смене вида</span>`;}return;}if(d.wbPersonal){const f=field(d.wbPersonal);if(f.type==='number'&&n.value!==''&&!Number.isFinite(Number(n.value)))return toast('Введите корректное число.');personal.values[d.row]||={};personal.values[d.row][d.wbPersonal]=f.type==='number'&&n.value!==''?Number(n.value):n.value;savePersonal();renderData();return;}
    if(d.wbSelect){n.checked?selected.add(d.wbSelect):selected.delete(d.wbSelect);renderData();return;}if('wbSelectAll' in d){selected=n.checked?new Set(data().map(r=>r.id)):new Set();renderData();return;}
    if(d.wbVisible){if(!n.checked&&cols().length===1){n.checked=true;return toast('Оставьте хотя бы одно видимое поле.');}settings().columns.find(c=>c.id===d.wbVisible).hidden=!n.checked;refreshSettings();}
    if(d.wbWidth){const c=settings().columns.find(c=>c.id===d.wbWidth);c.width=Math.max(80,Math.min(480,Number(n.value)||130));refreshSettings();}
    if(d.wbColor){settings().columns.find(c=>c.id===d.wbColor).color=palette.includes(n.value)?n.value:'';refreshSettings();}
    if(d.wbRule){const [key,i,prop]=d.wbRule.split(':');settings()[key][Number(i)][prop]=n.value;refreshSettings();}
    if('wbGroup' in d){if(settings().groups.some((g,i)=>i!==Number(d.wbGroup)&&g===n.value)){toast('Этот уровень уже выбран.');return settingsDialog('groups');}settings().groups[Number(d.wbGroup)]=n.value;personal.collapsed=[];refreshSettings();}
    if(d.wbSetting){settings()[d.wbSetting]=n.type==='checkbox'?n.checked:n.value;savePersonal();render();}
    if(d.wbPersonalSetting){personal[d.wbPersonalSetting]=n.checked;savePersonal();render();}
    if(d.wbWidget){personal.widgets=n.checked?[...personal.widgets.filter(x=>x!==d.wbWidget),d.wbWidget]:personal.widgets.filter(x=>x!==d.wbWidget);savePersonal();render();configureDialog();}
    if(d.wbQuick){personal.quick=n.checked?[...personal.quick.filter(x=>x!==d.wbQuick),d.wbQuick]:personal.quick.filter(x=>x!==d.wbQuick);savePersonal();render();}
    if(d.wbTask){personal.tasks.find(t=>t.id===d.wbTask).done=n.checked;savePersonal();}
  });
  document.addEventListener('paste',e=>{if(!opts)return;const n=e.target;if(n.dataset.wbSheet){const text=e.clipboardData.getData('text/plain');if(!/[\t\n]/.test(text))return;e.preventDefault();const address=n.dataset.wbSheet,col=address.charCodeAt(0)-65,row=Number(address.slice(1))-1,lines=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(l=>l.split('\t'));if(row+lines.length>10||lines.some(l=>col+l.length>8))return toast('Диапазон выходит за границы личного листа 10 × 8.');for(let i=0;i<lines.length;i++)for(let j=0;j<lines[i].length;j++)personal.sheet[String.fromCharCode(65+col+j)+(row+i+1)]=lines[i][j];savePersonal();render();toast('Диапазон вставлен в личный лист.');return;}if(n.dataset.wbEdit){const text=e.clipboardData.getData('text/plain');if(!/[\t\n]/.test(text))return;e.preventDefault();pasteGrid(text,n.dataset.row,n.dataset.wbEdit);}});
  document.addEventListener('keydown',e=>{if(!opts||$('#wb-dialog')?.open||$('#modal')?.open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('input,textarea,select,[contenteditable="true"]')&&section==='purchases'&&personal.tab!=='calc'){if(editable()){e.preventDefault();undoDraft(e.shiftKey);}return;}if(e.target.dataset.wbSheet&&['ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();const a=e.target.dataset.wbSheet,n=Number(a.slice(1))+(e.key==='ArrowUp'?-1:1);if(n>=1&&n<=10)$(`[data-wb-sheet="${a[0]+n}"]`,main)?.focus();}});
  window.addEventListener('storage',e=>{if(opts&&e.key===NS+'shared'){shared=read('shared',()=>E().createState(catalog()));shared.notes||=[];close();undo=[];redo=[];render();toast('Общая версия обновилась в другой вкладке.');}});
  function mount(options){opts=options;main=opts.main;profile=opts.profile;section=opts.section;if(profile!==lastProfile){close();selected=new Set();undo=[];redo=[];calcActive='D5';lastProfile=profile;}load();render();}
  return {render:mount,close(){close();opts=null;}};
})();
